<form method="post" id="saleForm"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(generateCsrfToken()) ?>"><input type="hidden" name="complete_sale" value="1"><input type="hidden" name="idempotency_key" value="<?= htmlspecialchars(bin2hex(random_bytes(16))) ?>"><input type="hidden" name="student_id" id="saleStudentId"><input type="hidden" name="items_json" id="saleItemsJson">
 <div class="row g-4"><div class="col-lg-4"><div class="card border-0 shadow-sm"><div class="card-body"><h5>1. Student</h5><div class="input-group"><input id="saleStudentNumber" class="form-control" placeholder="Student number"><button type="button" id="findSaleStudent" class="btn btn-primary">Find</button></div><div id="saleStudentInfo" class="d-none mt-3 bg-light rounded p-3"><strong id="saleStudentName"></strong><div class="small text-muted" id="saleStudentMeta"></div></div></div></div></div>
 <div class="col-lg-8"><div class="card border-0 shadow-sm"><div class="card-body"><div class="d-flex flex-wrap justify-content-between gap-2 align-items-center mb-3"><div><h5 class="mb-1">2. Approved School Items</h5><p class="small text-muted mb-0">Items are filtered by the selected student's program and year level.</p></div><input id="catalogSearch" class="form-control" style="max-width:260px" placeholder="Search school items" disabled></div><div id="catalogState" class="alert alert-info mb-0">Search a student to load eligible school items.</div><div id="catalogItems" class="table-responsive d-none"><table class="table align-middle"><thead><tr><th>Category</th><th>Item / Variant</th><th class="text-end">Price</th><th style="width:110px">Qty</th></tr></thead><tbody id="catalogRows"></tbody></table></div><div id="catalogPagination" class="d-flex justify-content-between align-items-center mt-2 d-none"><small id="catalogPageSummary" class="text-muted"></small><div class="btn-group btn-group-sm"><button type="button" class="btn btn-outline-secondary" id="catalogPrevious">Previous</button><button type="button" class="btn btn-outline-secondary" id="catalogNext">Next</button></div></div><div id="saleCartSummary" class="small text-muted mt-2">No items selected.</div><div class="row mt-3"><div class="col-md-4"><label class="form-label">Sale Total</label><input id="saleTotal" class="form-control fw-bold" readonly value="0.00"></div><div class="col-md-4"><label class="form-label">Cash Received</label><input name="cash_received" id="saleCash" class="form-control" type="number" min="0" step="0.01" required></div><div class="col-md-4"><label class="form-label">Change</label><input id="saleChange" class="form-control" readonly value="0.00"></div></div><div class="mt-3"><label class="form-label">Remarks</label><textarea name="remarks" class="form-control" rows="2" placeholder="Optional sale notes"></textarea></div><button class="btn btn-success mt-3" id="completeSale" disabled><i class="ti ti-printer me-1"></i>Complete Sale & Issue OR</button></div></div></div></div></form>
</div>
<div class="container-fluid pb-4"><div class="card border-0 shadow-sm"><div class="card-body"><div class="d-flex justify-content-between"><h5 class="mb-3">My Recent School Sales</h5><small class="text-muted">Only transactions processed by your account</small></div><?php if ($salesHistoryUnavailable): ?><div class="alert alert-warning mb-0">Recent school sales are temporarily unavailable.</div><?php else: ?><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>OR</th><th>Student</th><th>Items</th><th>Date</th><th class="text-end">Total</th><th></th></tr></thead><tbody><?php if ($recentSales): foreach ($recentSales as $sale): ?><tr><td class="fw-bold"><?= htmlspecialchars($sale['receipt_number']) ?></td><td><?= htmlspecialchars($sale['full_name']) ?><small class="d-block text-muted"><?= htmlspecialchars($sale['student_number']) ?></small></td><td><?= htmlspecialchars($sale['items']) ?></td><td><?= htmlspecialchars($sale['sold_at']) ?></td><td class="text-end">PHP <?= number_format((float)$sale['total_amount'],2) ?></td><td><a class="btn btn-sm btn-outline-primary" target="_blank" rel="noopener" href="print-receipt.php?cash_sale_id=<?= (int)$sale['cash_sale_id'] ?>"><i class="ti ti-printer"></i></a></td></tr><?php endforeach; else: ?><tr><td colspan="6" class="text-center text-muted py-4">No school sales recorded yet.</td></tr><?php endif; ?></tbody></table></div><?php endif; ?></div></div></div>
<script>
const findBtn=document.getElementById('findSaleStudent'),studentInput=document.getElementById('saleStudentNumber'),studentId=document.getElementById('saleStudentId'),studentName=document.getElementById('saleStudentName'),studentMeta=document.getElementById('saleStudentMeta'),studentInfo=document.getElementById('saleStudentInfo'),saleTotal=document.getElementById('saleTotal'),saleItems=document.getElementById('saleItemsJson'),saleCash=document.getElementById('saleCash'),saleChange=document.getElementById('saleChange'),completeSale=document.getElementById('completeSale'),catalogState=document.getElementById('catalogState'),catalogItems=document.getElementById('catalogItems'),catalogRows=document.getElementById('catalogRows'),catalogSearch=document.getElementById('catalogSearch');
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const selectedQuantities=new Map(),catalogPageSize=50;let catalogPage=1,catalogTotalPages=1,catalogRequest=0,searchTimer;
function captureVisibleQuantities(){document.querySelectorAll('.sale-quantity').forEach(input=>{const id=Number(input.dataset.id),quantity=Math.max(0,Math.min(100,parseInt(input.value,10)||0));if(quantity)selectedQuantities.set(id,{quantity,price:Number(input.dataset.price)});else selectedQuantities.delete(id);});}
function calc(){captureVisibleQuantities();let total=0,items=[];selectedQuantities.forEach((entry,id)=>{total+=entry.quantity*entry.price;items.push({sale_variant_id:id,quantity:entry.quantity});});saleTotal.value=total.toFixed(2);saleItems.value=JSON.stringify(items);const cash=parseFloat(saleCash.value)||0;saleChange.value=Math.max(0,cash-total).toFixed(2);completeSale.disabled=!(studentId.value&&items.length&&total>0&&cash>=total);document.getElementById('saleCartSummary').textContent=items.length?items.reduce((sum,item)=>sum+item.quantity,0)+' item(s) selected · PHP '+total.toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2}):'No items selected.';}
function renderPagination(total,page){catalogPage=page;catalogTotalPages=Math.max(1,Math.ceil(total/catalogPageSize));const pagination=document.getElementById('catalogPagination');pagination.classList.toggle('d-none',total<=catalogPageSize);document.getElementById('catalogPageSummary').textContent='Page '+page+' of '+catalogTotalPages+' · '+total+' catalog items';document.getElementById('catalogPrevious').disabled=page<=1;document.getElementById('catalogNext').disabled=page>=catalogTotalPages;}
async function loadCatalog(){if(!studentId.value)return;captureVisibleQuantities();const request=++catalogRequest;catalogState.className='alert alert-info mb-0';catalogState.textContent='Loading eligible school items…';catalogState.classList.remove('d-none');catalogItems.classList.add('d-none');catalogRows.replaceChildren();const params=new URLSearchParams({action:'items',per_page:String(catalogPageSize),page:String(catalogPage),student_id:studentId.value,q:catalogSearch.value.trim()});try{const r=await fetch('../../api/cashier-school-sales-catalog.php?'+params.toString(),{credentials:'same-origin'}),d=await r.json();if(request!==catalogRequest)return;if(!r.ok||!d.ok)throw new Error(d.message||'Unable to load school items.');const data=d.data||{},items=data.items||[];for(const item of items){for(const variant of item.variants||[]){const price=variant.current_price,id=Number(variant.variant_id),selected=selectedQuantities.get(id),row=document.createElement('tr');row.innerHTML='<td>'+esc(item.category.category_name)+'</td><td><strong>'+esc(item.item_name)+'</strong><small class="d-block text-muted">'+esc(variant.variant_name)+(variant.size_label?' · '+esc(variant.size_label):'')+'</small></td><td class="text-end">₱ '+Number(price.amount).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})+'</td><td><input class="form-control sale-quantity" type="number" min="0" max="100" value="'+(selected?.quantity||0)+'" data-id="'+id+'" data-price="'+Number(price.amount)+'" aria-label="Quantity for '+esc(item.item_name)+' '+esc(variant.variant_name)+'"></td>';catalogRows.appendChild(row);}}renderPagination(Number(data.total||0),Number(data.page||catalogPage));if(!catalogRows.children.length){catalogState.className='alert alert-warning mb-0';catalogState.textContent='No approved school items match this student and search.';calc();return;}catalogState.classList.add('d-none');catalogItems.classList.remove('d-none');document.querySelectorAll('.sale-quantity').forEach(input=>input.addEventListener('input',calc));calc();}catch(error){if(request!==catalogRequest)return;catalogState.className='alert alert-danger mb-0';catalogState.textContent=error.message||'Unable to load school items.';catalogState.classList.remove('d-none');calc();}}
findBtn.onclick=async()=>{const n=studentInput.value.trim();if(!n)return;findBtn.disabled=true;completeSale.disabled=true;try{const r=await fetch('../../api/fetch_cash_sale_student.php?student_number='+encodeURIComponent(n),{credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.success)throw new Error(d.message||'Student lookup failed.');const changed=studentId.value!==String(d.student_id);if(changed){selectedQuantities.clear();saleCash.value='';catalogPage=1;}studentId.value=d.student_id;studentName.textContent=d.name+' ('+d.student_number+')';studentMeta.textContent=d.course_year;studentInfo.classList.remove('d-none');catalogSearch.disabled=false;await loadCatalog();}catch(error){studentId.value='';studentInfo.classList.add('d-none');catalogState.className='alert alert-danger mb-0';catalogState.textContent=error.message||'Student lookup failed.';catalogState.classList.remove('d-none');catalogItems.classList.add('d-none');calc();}finally{findBtn.disabled=false;}};
document.getElementById('catalogPrevious').addEventListener('click',()=>{if(catalogPage>1){catalogPage--;loadCatalog();}});document.getElementById('catalogNext').addEventListener('click',()=>{if(catalogPage<catalogTotalPages){catalogPage++;loadCatalog();}});
catalogSearch.addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{catalogPage=1;loadCatalog();},250);});saleCash.addEventListener('input',calc);
const prefillStudent=new URLSearchParams(window.location.search).get('student_number');if(prefillStudent){studentInput.value=prefillStudent;findBtn.click();}
</script>
